import subprocess, re, sys

def git(*args):
    args = [a if isinstance(a, bytes) else a.encode() for a in args]
    p = subprocess.run([b'git'] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        sys.stderr.write(p.stderr.decode('utf-8', 'replace'))
        sys.exit(p.returncode)
    return p.stdout

def parse_hunks(data):
    hunk_re = re.compile(rb'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')
    hunks = []
    cur = None
    for line in data.splitlines():
        m = hunk_re.match(line)
        if m:
            if cur is not None:
                hunks.append(cur)
            cur = dict(old_start=int(m.group(1).decode()), minus=[], plus=[])
        elif cur is not None:
            if line.startswith(b'-') and not line.startswith(b'---'):
                cur['minus'].append(line[1:])
            elif line.startswith(b'+') and not line.startswith(b'+++'):
                cur['plus'].append(line[1:])
    if cur is not None:
        hunks.append(cur)
    return hunks

out = git('diff', '--name-only', '--diff-filter=U', '-z')
paths = [p for p in out.split(b'\0') if p]
for path in paths:
    base_hash = git('rev-parse', b':1:' + path).strip()
    ours_hash = git('rev-parse', b':2:' + path).strip()
    theirs_hash = git('rev-parse', b':3:' + path).strip()
    base_data = git('cat-file', 'blob', base_hash)
    theirs_data = git('cat-file', 'blob', theirs_hash)
    diff = git('diff', '-U0', '--no-color', base_hash, ours_hash)
