            if old_start == 0:
                insert_pos = 0
            else:
                anchor = None
                idx = old_start - 1
                if 0 <= idx < len(base_lines):
                    anchor = base_lines[idx]
                if anchor is not None and anchor in new_lines:
                    insert_pos = new_lines.index(anchor) + 1
